// Minimal adversarial helper that reenters c during a payable call or any call that sends value.
// To ensure it can trigger during assignment in the mutant we provide a fallback that attempts
// to call back into c.setOwner with a different address. This models an adversarial counterparty
// whose code executes during the assignment step (e.g., via a low level call in a more complex
// scenario). Here it will only run when the mutant's redundant assignment sequence allows
// reentrancy; the reference remains robust.
contract ReentrantHelper {
    C public c;
    bool public reentered;

    constructor(C _c) {
        c = _c;
    }

    // fallback invoked if any call with data/value hits this contract
    fallback() external payable {
        // attempt a reentrant call only once to try to disturb the mutant's second assignment
        if (!reentered) {
            reentered = true;
            // try calling setOwner with this helper again (no effect expected in correct contract)
            // wrap in try/catch to avoid bubbling reverts into the fallback
            try c.setOwner(address(this)) {
            } catch {
            }
        }
    }
}

